nodes.statement:
If $X\in M_n(\C)$ is accretive, let $m(X)$ be the number of distinct
positive singular values, with $m(0)=0$. Then
\begin{equation}
0\leq\Ree X\leq m(X)|X|\leq\rank(X)|X|\leq n|X|.
\end{equation}

For $m\ge2$, the length enumerator is
\begin{equation}
 \sum_{\ell\ge0}a_\ell(2^m+1)z^\ell
 =z^m(1+z+z^2)+\sum_{r=1}^{R_m}z^{m-r}.
\end{equation}
In particular,
\begin{equation}
 b_m:=a(2^m+1)=3+R_m.
\end{equation}

For $m\ge2$, the sum-constrained digit refinement is
\begin{align*}
 W_{2^m+1}(z,t)={}&z^m t^{\max(0,m-3)}
       +z^{m+1}t^{m-2}+z^{m+2}t^{m-1}\\
       &+\sum_{r=1}^{R_m}z^{m-r}t^{\max(0,m-2^r-r-2)}.
\end{align*}
For $v\ge0$, $W_{2^v(2^m+1)}(z,t)=(zt)^vW_{2^m+1}(z,t)$.

The disjoint sets
\begin{align*}
 A={}&\{10,17,21,23,24,27,38,45,46,48,56,65,68,77,80,84,95,141\},\\
 B={}&\{11,16,20,22,25,26,39,44,47,49,57,64,69,76,81,85,94,140\}
\end{align*}
satisfy $F(A)=F(B)$. In particular, the answer to Problem~5.6 is negative
even when both sides have eighteen parameters and all thirty-six parameters
are distinct. Moreover, $\sum_{a\in A}a=\sum_{b\in B}b=965$.

For every subgroup $H$ of a finite group $G$,
\begin{equation}
 \PP_G(H)=\prod_{d\in\DD_H}a(t_H(d)),\qquad
 a(t)=\frac{t!}{t^t}\quad(t\geq1).
\end{equation}

For positive integers $s,t$, $a(st)\geq a(s)^t a(t)^s$. Consequently,
if $A\leq G$ and $B\leq K$, then
\begin{equation}
 \PP_{G\times K}(A\times B)\geq
 \PP_G(A)^{[K:B]}\PP_K(B)^{[G:A]}.
\end{equation}

For every integer $n\ge1$,
\begin{equation}
 a(n+1)=\prod_{k=1}^{n}
 \left(1-2\left(\floor{\frac{k^n}{n}}
                  -\floor{\frac{k^n-1}{n}}\right)\right)
 =(-1)^{n/\rad(n)}
 =\begin{cases}1,&4\mid n,\\-1,&4\nmid n.\end{cases}
\end{equation}
All division inside a floor is rational division; in particular the
subtraction by $1$ precedes the second division.

We have $I_0=1$, $I_1=1/2$, and, for $m\ge2$,
\begin{equation}
 I_m=\begin{cases}
 -1/(m^2-1),&m\ \text{even},\\
 1/(m+1),&m\equiv1\pmod4,\\
 -1/(m-1),&m\equiv3\pmod4.
 \end{cases}
\end{equation}
Consequently $a(0)=1$ and, for $m\ge1$, $a(m)=1$ exactly when
$m\equiv1\pmod4$, and $a(m)=-1$ otherwise. Also
\begin{equation}
 d(0)=1,\qquad
 d(m)=\begin{cases}
 m^2-1,&m\ge2\ \text{even},\\
 m+1,&m\equiv1\pmod4,\\
 m-1,&m\equiv3\pmod4.
 \end{cases}
\end{equation}
The odd branches include $m=1$ in the second case.

For positive integers $k,s$, the group $\Gk$ has an $s$-spanning pair
if and only if one of the following conditions holds:
\begin{align*}
&s\text{ is odd}, &&2k\le s^2-1;\\
&s\text{ is even}, &&2k\le s^2-s;\\
&s\equiv0\pmod4,\quad k\text{ is even},
&&s^2-s<2k\le s^2;\\
&s\equiv2\pmod4,\quad k\equiv2\pmod4,
&&s^2-s<2k\le s^2.
\end{align*}

For $n\geq1$, $v=\val(n)$, every integer $r\geq1$, and every function
$w$ on the positive integers with complex values,
\begin{equation}
 \sum_{d\mid n}m(d)^r w(d)=w(1)+2^r\sum_{j=1}^v w(2^j).
\end{equation}

For real $a\geq0$, set $F_a(n)=\sum_{j=0}^{\val(n)}2^{aj}$.
Then
\begin{align*}
 \sum_{n\geq1}F_a(n)x^n
 &=\sum_{j\geq0}\frac{2^{aj}x^{2^j}}{1-x^{2^j}}
 &&(|x|<1),\\
 \sum_{n\geq1}\frac{F_a(n)}{n^s}
 &=\frac{\zeta(s)}{1-2^{a-s}}
 &&(\Re s>\max\{1,a\}).
\end{align*}
The cases $a=1,2,3$ are A038712, A296306, A318935, respectively.
Also $F_0(n)=\val(n)+1$
and $\sum_{d\mid n}m(d)=2F_0(n)-1=H_{3589}(n)$.

Let $(c_0,c_1,c_2,c_3)=(16,17,12,17)$ and
$(d_0,d_1,d_2,d_3)=(32,38,24,30)$. Then $a(0)=1$ and, for $n\ge1$,
\begin{equation}
a(n)=\frac{63n^2+c_{n\bmod4}}8.
\end{equation}
For every $n\ge0$,
\begin{equation}
b(n)=\frac{84n^3+126n^2+104n+d_{n\bmod4}}{32}.
\end{equation}
With $P(x)=1+8x+14x^2+17x^3+14x^4+8x^5+x^6$,
\begin{equation}
\sum_{n\ge0}a(n)x^n=\frac{P(x)}{(1-x)^3(1+x)(1+x^2)},\qquad
\sum_{n\ge0}b(n)x^n=\frac{P(x)}{(1-x)^4(1+x)(1+x^2)}.
\end{equation}

For $p,q\ge0$,
\begin{equation}
|\Hh(p,q)|=C(p,q):=\frac{p^2+4pq+q^2+3p+3q+2}{2}.
\end{equation}
The number of planar points with residual exactly $r$ is $C(p,q)$ for
$r=0$, and $3(p+q)+6r$ for $r\ge1$.

The metric $d$ is of negative type, and all nonempty principal submatrices
of $Z$ are positive definite. The deletion procedure stops after two solves
with
\begin{equation}
 p=\frac1{61601}(15961,22820,0,0,22820)^T.
\end{equation}
Nevertheless, for
\begin{equation}
 p'=\frac{999}{1000}p+\frac1{1000}e_3
 =\frac1{61601000}(15945039,22797180,0,61601,22797180)^T
\end{equation}
one has
\begin{equation}
 E(p)-E(p')=\frac{1707687919}{246404000000000}>0.
\end{equation}

For every real $r\geq3$, the triangle of step $m=-r$ satisfies
\begin{enumerate}
\item $T_{-r}(n,k)>0$ for every positive even $n$ and $1\leq k\leq n$;
\item $T_{-r}(n,k)<0$ for every odd $n\geq3$ and $1<k<n$.
\end{enumerate}
In particular, the three OEIS conjectures and Conjecture~2 of
\cite{chen} hold for their stated integer parameters.

For integer $m$, every positive even row is entrywise nonnegative
if and only if $m\leq-3$ or $m\geq0$. For exactly these parameters,
every positive even row is in fact strictly positive.

Every four-qubit density matrix satisfies
\begin{equation}
 \norm{T_{AB}}_F^2+\norm{T_{AC}}_F^2+\norm{T_{AD}}_F^2\leq3.
\end{equation}
The constant is attained by both $|0000\rangle$ and
$(|0000\rangle+|1111\rangle)/\sqrt2$.

For every four-qubit state, pure or mixed,
\begin{equation}
 v_{B|A}^{2/3}+v_{C|A}^{2/3}+v_{D|A}^{2/3}\leq1.
\end{equation}
Equality holds for a Bell state on $AB$ tensored with any state on $CD$.

For the state \eqref{eq:rho},
\begin{equation}
 \E(\rho)\le\frac{417965512477}{90316800000000}
 <\min_{S(a,b,d)\in\Sep_3}\D(\rho,S(a,b,d))
 =\frac{109}{23520}.
\end{equation}
Thus Eqs.~(A8), (A11), and their common form in Eq.~(16) of \cite{CAW}
do not contain a closest fully separable state at this instance.

The contents of Copeland's array are
\begin{equation}
 c_n=\begin{cases}
 1,& n=0,\ n=1,\ \text{or }n\text{ is even},\\
 2,& n\geq3\text{ is odd}.
 \end{cases}
\end{equation}

For every $d\geq2$, every full traceless Hermitian ONB, and every density
matrix $\rho$ as above,
\begin{equation}
 \CH\geq(d-1)(1+P),\qquad
 \CN\leq d^2+d-1-P,
\end{equation}
and consequently
\begin{equation}
 \frac{\CN}{\CH}
 \leq \frac{d^2+d-1-P}{(d-1)(1+P)}\leq d+1.
\end{equation}
The second inequality is strict unless $\rho=\Id_d/d$.
At $\rho=\Id_d/d$ the ratio is $d+1$.

If $\lambda_1,\ldots,\lambda_d$ are the eigenvalues of $\rho$, then
\begin{equation}
 \CH=d-P+\sum_{a<b}|\lambda_a-\lambda_b|.
\end{equation}
In particular $\CH\geq(d-1)(1+P)$.

At each $P\in[1/d,1]$, the minimum Holevo cost over states of purity $P$ is
\begin{equation}
 m_d(P)=d-P+\sqrt{(d-1)(dP-1)}.
\end{equation}
It is attained by the depolarized pure states of
Corollary~\ref{cor:depolarized}, with $p=\sqrt{(dP-1)/(d-1)}$.
For $P>1/d$, the other minimizing spectra, when distinct, have one smaller
eigenvalue and $d-1$ equal larger eigenvalues; they exist exactly when
$P\leq1/(d-1)$. Consequently,
\begin{equation}
 \frac{\CN}{\CH}\leq F_d(P):=
 \frac{d^2+d-1-P}{m_d(P)}
 \leq \frac{d^2+d-1-P}{(d-1)(1+P)}\leq d+1.
\end{equation}
The function $F_d$ is strictly decreasing on $[1/d,1]$.

For an Alice filter, write its positive effect, up to a positive scalar,
as $K^\dagger K=\id+u\cdot\sigma$, $|u|<1$. Then
\begin{equation}
 \F(\rho_K)^2=
 \frac{(1-|u|^2)(E-|b|^2)+|b+T^{\mathsf T}u|^2}
 {(1+a\cdot u)^2}.
\end{equation}

For the normalized solution of \eqref{eq:A},
\begin{equation}
 A^2-x^2-2x^3\in9\Z[[x]].
\end{equation}
Consequently $9\mid\coef{n}{A^2}$ for every $n>3$,
as conjectured in A389474, FORMULA (3).

For every $k\ge0$,
\begin{equation}
 A(x)^{3k}\equiv A(x^3)^k\pmod3.
\end{equation}
The normalized solution $B$ of \eqref{eq:B} satisfies
\begin{equation}
 B(x)^3\equiv B(x^3),\qquad
 B(x)^2\equiv x^2+2B(x^3)\pmod3.
\end{equation}
These prove A389474, FORMULA (4), and A389475,
FORMULA (4.a), (4.b).

Let $H=(g_{i+k})_{i,k<N}$ have determinant $1$ and let $c,d$ satisfy
\eqref{orth}, with $c$ monic of degree $N$ and $\deg d<N$.
Extend their coefficients by zero. Then
\begin{equation}
 (H^{-1})_{ik}=-\sum_{v=0}^{k}
 (c_{i+k+1-v}d_v-d_{i+k+1-v}c_v).
\end{equation}

Let \(U(t)\in1+t\mathbb Z[[t]]\), and write
\(c(n,k)=[t^k]U(t)^n\) for \(n\ge1\), \(k\ge0\).
Let the nonnegative exponent $E(n,k)$ have one of the forms
\begin{align*}
 E(n,k)&=rk+s &&(r,s\ge1),\\
 E(n,k)&=rn+sk+q &&(r\ge1,\ s,q\ge0),\\
 E(n,k)&=n+k-1.
\end{align*}
All parameters here are integers. Then
the series
\begin{equation}
 A_{U,E}(x)=\exp\left(\sum_{n\ge1,k\ge0}
                      c(n,k)^{E(n,k)}\frac{x^{n+k}}{n}\right)
\end{equation}
belongs to \(1+x\mathbb Z[[x]]\).

For \(U\in\mathbb Z[[t]]\), \(n\ge1\), \(k\ge0\), and prime \(p\),
\begin{align}
 n&\mid k\,c(n,k),\\
 c(pn,pk)&\equiv c(n,k)\pmod {p^{v_p(n)+1}}.
\end{align}

Under the hypotheses of Theorem~\ref{thm:general}, put
\(F(n,k)=c(n,k)^{E(n,k)}\). Then
\begin{equation}
 n\mid kF(n,k),\qquad
 F(pn,pk)\equiv F(n,k)\pmod {p^{v_p(n)+1}}
\end{equation}
for every \(n\ge1\), \(k\ge0\), and prime \(p\).

Let \(F(n,k)\in\mathbb Z\), \(n\ge1\), \(k\ge0\), satisfy
\eqref{eq:array}. Define
\begin{equation}
 g_m=\sum_{n=1}^m\frac{m}{n}F(n,m-n),\qquad m\ge1.
\end{equation}
Then \(g_m\in\mathbb Z\), and for every prime \(p\), \(m\ge1\),
\begin{equation}
 g_{pm}\equiv g_m\pmod {p^{v_p(m)+1}}.
\end{equation}
Consequently
\begin{equation}
 \exp\left(\sum_{m\ge1}g_m\frac{x^m}{m}\right)
  =\prod_{m\ge1}(1-x^m)^{-h_m}\in1+x\mathbb Z[[x]],
 \qquad h_m=\frac1m\sum_{d\mid m}\mu(d)g_{m/d}\in\mathbb Z.
\end{equation}

Suppose integers $c_m$, $m\geq1$, satisfy
\begin{equation}
 c_{pm}\equiv c_m\pmod{p^{\vp(m)+1}}
 \qquad(p\text{ prime},\ m\geq1).
\end{equation}
Then $\exp(\sum_{m\geq1}c_mx^m/m)$ has integer coefficients.

Let $n\geq1$, $b,t\geq0$ be integers with $n\mid tb$. Then
\begin{equation}
 b^{pt+1}\equiv b^{t+1}\pmod{p^{\vp(n)+1}}
 \quad(p\text{ prime}).
\end{equation}
Also, if $e\geq n$ and $n\mid eb$, then
\begin{equation}
 b^{pe}\equiv b^e\pmod{p^{\vp(n)+1}}.
\end{equation}

Let $F(n,k)\in\Z$ for $n\geq1$, $k\geq0$. Suppose
\begin{equation}
 n\mid kF(n,k),\qquad
 F(pn,pk)\equiv F(n,k)\pmod{p^{\vp(n)+1}}
\end{equation}
for every prime $p$. Then
$\exp(\sum_{n\geq1,k\geq0}F(n,k)x^{n+k}/n)\in1+x\Z[[x]]$.

There are unique series $A,B\in x+x^2\Q[[x]]$ satisfying, respectively,
\begin{align}
 A(x^2+2x^3+2A(x)^2)&=3A(x)^2,\\
 B(3x^2)&=2x^2+B(x)^2-2B(x)^3.
\end{align}
Both series have integer coefficients. Moreover,
\begin{align}
 A(x)^{3k}&\equiv A(x^3)^k\pmod3 &&(k\geq0),\\
 A(x)^2&\equiv x^2+2x^3\pmod9,\\
 B(x)^3&\equiv B(x^3)\pmod3,\\
 B(x)^2&\equiv x^2+2B(x^3)\pmod3.
\end{align}

For all $n,k\geq1$,
\begin{equation}
 T(n,k)=b(n)+b(k)-2.
\end{equation}
Consequently,
\begin{equation}
 a(2m+1)=2^{m+1}+4,\qquad a(2m+2)=3\cdot2^m+4\quad(m\geq0),
\end{equation}
and $\sum_{n\geq1}a(n)x^n=x(6+x-11x^2)/((1-x)(1-2x^2))$.

For every integer $q\geq2$,
\begin{equation}
 S_q(x)=\frac{qx\bigl(1-(q-3)x-(q-1)x^2\bigr)}
 {(1-(q-1)x)(1-(q-2)x-qx^2)}.
\end{equation}
The initial values are $\aq(0)=1$, $\aq(1)=q$, $\aq(2)=q^2$, and
\begin{equation}
 \aq(n+3)=(2q-3)\aq(n+2)+(-q^2+4q-2)\aq(n+1)
                -q(q-1)\aq(n)\qquad(n\geq0).
\end{equation}

For $n\geq1$, the count $a_8(n)$ in A268943 has generating function
\[
 S_8(x)=\frac{8x(1-5x-7x^2)}{(1-7x)(1-6x-8x^2)}
\]
and satisfies
\begin{equation}
 a_8(n)=\frac{-272\,7^n+(153-37\sqrt{17})(3-\sqrt{17})^n
                    +(153+37\sqrt{17})(3+\sqrt{17})^n}{34}.
\end{equation}
In particular, $a_8(n+3)=13a_8(n+2)-34a_8(n+1)-56a_8(n)$ for $n\geq0$.

For every such relation,
\begin{equation}
 S_R(x)=\frac{qx\bigl(1-(q-3)x-(q+d-2)x^2\bigr)}
 {(1-(q-1)x)(1-(q-2)x-(q+d-1)x^2)}.
\end{equation}
In particular, no other features of $R$ affect these counts. At $d=q-1$
this reproves Fried's Theorem~4~\cite{fried}: if $F_q(x)$ denotes its
displayed rational function, then
\[
 1+S_R(x)=F_q(x)=
 \frac{1-(q-3)x-2(q-2)x^2-(q-2)x^3}
 {1-(2q-3)x+(q-1)(q-4)x^2+2(q-1)^2x^3}.
\]
Here the constant term includes the empty word. The positive-index counts
agree with Fried's enumeration. Writing $b_q(n)=a_R(n)$ in this case gives
\begin{equation}
 b_q(n+3)=(2q-3)b_q(n+2)+(-q^2+5q-4)b_q(n+1)
             -2(q-1)^2b_q(n)\quad(n\geq1),
\end{equation}
with $b_q(1)=q$, $b_q(2)=q^2$, $b_q(3)=q^3-q$.
This proves the seven empirical column recurrences of A269467~\cite{unequal}.
For $q=k+1$, its rows $n=1,2,3$ are the same as those of A268944;
the next four are
\begin{align*}
 b_{k+1}(4)&=k^4+4k^3+4k^2+k,\\
 b_{k+1}(5)&=k^5+5k^4+7k^3+2k^2-k,\\
 b_{k+1}(6)&=k^6+6k^5+11k^4+4k^3-k^2+k,\\
 b_{k+1}(7)&=k^7+7k^6+16k^5+8k^4-k^3-k.
\end{align*}
Thus all seven displayed row formulas in A269467 follow as well.

Let $c_R(n,r)$ count these words of length $n$ with exactly $r$ equality
events. For $r\geq1$,
\begin{equation}
 \sum_{n\geq1}c_R(n,r)x^n=
 \frac{q\,d^{r-1}x^{2r}}
 {(1+x)^{r-1}(1-(q-1)x)^{r+1}},
\end{equation}
where $d^0=1$, including when $d=0$. In particular there are no words
with $n<2r$, and $c_R(2r,r)=q\,d^{r-1}$.

For every integer $n\geq13$,
\begin{align}
 a_n={}&a_{n-1}+30a_{n-2}+24a_{n-3}-95a_{n-4}-15a_{n-5}\notag\\
       &+64a_{n-6}-116a_{n-7}+16a_{n-8}+16a_{n-9}.
\end{align}
The difference between the left and right sides at $n=12$ is $-4160$.

Let $F_6(z)=\sum_{n\geq1}a_nz^n$ and
$D_6(z)=1-z-30z^2-24z^3+95z^4+15z^5-64z^6+116z^7-16z^8-16z^9$.
Then
\begin{equation}
 F_6(z)=\frac{8zN_6(z)}{D_6(z)},
\end{equation}
where
\begin{align*}
N_6(z)={}&85+347z-483z^2-2718z^3-1375z^4+2104z^5\\
 &+6276z^6+4796z^7-7734z^8-2893z^9+3400z^{10}-520z^{11}.
\end{align*}
No homogeneous constant-coefficient recurrence over $\mathbb Q$ of
order less than nine holds for all sufficiently large $n$.

For every $n\geq6$,
\begin{equation}
 a_n=2a_{n-1}+a_{n-2}-a_{n-3}-2a_{n-4}+a_{n-5}.
\end{equation}
Moreover, as a formal power series in $\Z[[x]]$,
\begin{equation}
 F(x)=\frac{x(2-x)(1-x^2-2x^3)}{(1-x)Q(x)}.
\end{equation}
The initial values are $a_1,\ldots,a_6=2,3,6,10,21,42$.

For every family satisfying \eqref{family}, every real parameter vector,
and every permutation $\tau$ of $I$,
\begin{equation}
\scal{\Theta_k(\tau)}=
\sum_{S\subseteq I}\eta(|S|)(-1)^{\inv(\tau,S)}
\prod_{i\in S}w_i\prod_{i\notin S}(1-w_i).
\end{equation}
No star condition is required.

Let $B_i$ be pairwise anticommuting bivectors with
$B_i^2=\varepsilon_i\in\{-1,1\}$. For arbitrary real $c_i,s_i$, put
$U_i=c_i+s_iB_i$. Then for every return order,
\begin{equation}
t(\Theta_k(\tau))=
\sum_{S\subseteq I}(-1)^{|S|(|S|+1)/2+\inv(\tau,S)}
\prod_{i\in S}(\varepsilon_i s_i^2)\prod_{i\notin S}c_i^2.
\end{equation}

Every mixed-sign family of Corollary~\ref{mixed} has the exact chain formula
\begin{equation}
t(U_1\cdots U_k)=
\begin{cases}
\prod_i c_i,&k\text{ even},\\
\prod_i c_i+t(B_I)\prod_i s_i,&k\text{ odd}.
\end{cases}
\end{equation}
The star condition is automatic unless $k\equiv3\pmod4$;
in that remaining case it is equivalent to $t(B_I)=0$.

If $X_1,\ldots,X_n$ are independent geometric random variables on
$\{1,2,\ldots\}$ with success probability $p\in(0,1]$ and $q=1-p$, then
\begin{equation}
 \E\Dstar(X)=
 \sum_{j=1}^{n}\frac{(-1)^{j+1}\binom nj}{1-q^j}
 +\frac{n-2}{p}-\frac{n-1}{p(2-p)}.
\end{equation}

For bipartite $G,H$, the following conditions are equivalent:
\begin{enumerate}
\item $G\sim H$;
\item some output relabelling $\sigma$ gives
$\Row B_{G^\sigma}=\Row B_H$;
\item some output relabelling $\sigma$ gives
$\rho_{G^\sigma}(S)=\rho_H(S)$ for every $S\subseteq O$.
\end{enumerate}

For all positive labels and all $1\le i\le n$,
\begin{equation}
 R_i=i+b_i=\fl{(i+1)\ph}-1,\qquad
 \deg_{J_n(1)}(v_i)=\min\{i,n-b_i\}.
\end{equation}
Consequently, for every $n\ge1$,
\begin{equation}
 \Delta_n=\fl{\frac{n+2}{\ph}}-1.
\end{equation}

Let $n,m\ge1$, set $x_n=\{(n+2)/\ph\}$ and $\alpha=2/\ph-1=\sqrt5-2$.
Then
\begin{equation}
 \Delta_{n+m}-\Delta_n-\Delta_m
 =\fl{x_n+x_m-\alpha}
 =\begin{cases}
 -1,&x_n+x_m<\alpha,\\
 0,&\alpha\le x_n+x_m<1+\alpha,\\
 1,&1+\alpha\le x_n+x_m.
 \end{cases}
\end{equation}
All three values occur for distinct orders at least three.

The first open problem on page 11 of \cite{original} has the following
partition. Set $\beta=5/\ph-3>0$, $k_0=1$ and, for $q\ge1$, set
\begin{equation}
 k_q=\left\lceil\frac{q-\alpha}{\beta}\right\rceil
     =\fl{(5q-1)\ph}+3q.
\end{equation}
Take $P_0=\{1,\ldots,5k_1-1\}$ and
$P_q=\{5k_q,\ldots,5k_{q+1}-1\}$ for $q\ge1$. These partition the
positive integers, and whenever $n=5k\in P_q$,
\begin{equation}
 \Delta_{5k}=3k+q.
\end{equation}
In particular $P_0=[1,44]$, $P_1=[45,99]$ and $P_2=[100,154]$.

If $A\in\mathcal M(E)$ has $\nssp$ and $E$ has $c$ weak components,
including isolated vertices, then
\begin{equation}
 n\ \leq\ \dim_\R\Zc(A)\ \leq\ \dim\ker B
   =m-n+c,\qquad m\geq2n-c.
\end{equation}

