Let $r$ be any integer, let $U_r$ be the zero-constant inverse of
$f_r(t)=t((1-t^2)^r-t)$, and write $U_r(x)/x=\sum_{n\geq0}a_n^{(r)}x^n$.
For integers $n\geq0$ and $s\geq1$,
\begin{equation}
 [x^n](U_r(x)/x)^s=\frac{s}{n+s}
 \sum_{k=0}^{\lfloor n/2\rfloor}
 \binom{2n+s-2k-1}{n-2k}
 (-1)^k\binom{-r(2n+s-2k)}{k}.
\end{equation}
Here $\binom{b}{k}=b(b-1)\cdots(b-k+1)/k!$ for any integer $b$,
and $\binom{b}{0}=1$. In particular, for $r\geq1$,
\begin{equation}
 a_n^{(r)}=\frac{1}{n+1}\sum_{k=0}^{\lfloor n/2\rfloor}
 \binom{2n-2k}{n}\binom{r(2n-2k+1)+k-1}{k}.
\end{equation}
All $a_n^{(r)}$ are integers, and they are strictly positive when $r\geq0$.
Every $U_r/x$ is algebraic and D-finite. The cases $r=1,2,3,-1$ give,
respectively, A001002, A392976, A392977 and A370839.

Let $B=U_1/x=\sum_{n\geq0}b_nx^n$, the generating function of A001002.
Then
\begin{align}
 B&=1+xB^2+x^2B^3,\\
 b_n&=\frac1{n+1}\sum_{j=\lceil n/2\rceil}^n
       \binom{n+j}{j}\binom{j}{n-j},\\
 5n(n+1)b_n&=11n(2n-1)b_{n-1}
       +3(3n-2)(3n-4)b_{n-2}\quad(n\geq2).
\end{align}
For $g(x)=x^2+x^3$ and $D=d/dx$ its two derivative representations are
\begin{align}
 B&=1+\frac1x\sum_{m\geq1}\frac{D^{m-1}g(x)^m}{m!},\\
 B&=\exp\left(\sum_{m\geq1}\frac{D^{m-1}(g(x)^m/x)}{m!}\right).
\end{align}
These are identities in $\Q[[x]]$; each coefficient receives finitely many terms.

For each fixed real $z>0$ there is a number $h(z)$ such that
\[
 \lim_{n\to\infty}\frac{\log F_n(z)}{n^2}
 =\lim_{n\to\infty}\frac{\log C_n(z)}{n^2}
 =\lim_{n\to\infty}\frac{\log T_n(z)}{n^2}
 =\lim_{n\to\infty}\frac{\log A_n(z)}{n^2}=h(z).
\]
Moreover $\frac14\log(1+z)\leq h(z)\leq\log(1+z)$.
In particular the total-count sequences A067958 and A212269 have
$n^2$th-root limit $\gam$.

For every $n\geq2$ and $v\in V$, the integer $E_n(v)$ is positive and
\begin{align}
 T(n,n^2+1)&=nE_n(v),\\
 T(n,n^2)&=(2n-1)E_n(v).
\end{align}
Consequently $T(n,n^2+1)>0$ and
\[
 \frac{T(n,n^2)}{T(n,n^2+1)}=\frac{2n-1}{n}.
\]
Moreover, for every $n\geq1$,
\begin{equation}
 T(n,n+1)=n!,\qquad T(n,n^2+1)=(n!)^n.
\end{equation}

A length-$(n^2-1)$ trail from $v$ visits every vertex. If its missing edge
is $(a,b)$ and its endpoint is $t$, exactly one of the following holds:
\begin{enumerate}
\item $b=v$ and $a=t$;
\item $a=b\ne v$ and $t=v$.
\end{enumerate}

Let $n\geq1$ and $t\geq1$. Let $u$ be the largest $t$-dense divisor
of $n$, and put $v=n/u$. Then $\gcd(u,v)=1$, and every prime divisor
of $v$ exceeds $t u$. Each maximal $t$-dense block of $\Div(n)$ is a
disjoint union of sets
\begin{equation}
 b\Div(u)=\{ba:a\mid u\},\qquad b\mid v.
\end{equation}
Consequently,
\begin{equation}
 \tau(u)\mid T_t(n,k),\qquad
 T_t(n,1)=T_t(n,r)=\min_k T_t(n,k)=\tau(u).
\end{equation}

